import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static final int MAXNODES = 1000007;
    static final long MODULUS = 1000000007L;
    static int p_value, k_value;
    static int[] count_array = new int[MAXNODES];
    static int[] visited_array = new int[MAXNODES];
    static int[] num_array = new int[MAXNODES];
    static List<Integer> divisor_list = new ArrayList<>();

    static void depth_first_search(int x, int start) {
        int count = 1;
        while ((long)k_value * x % p_value != start) {
            x = (int)((long)k_value * x % p_value);
            visited_array[x] = 1;
            count++;
        }
        num_array[count]++;
    }

    static boolean is_prime(int x) {
        if (x < 2) return false;
        for (int i = 2; i * i <= x; i++) {
            if (x % i == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        p_value = sc.nextInt();
        k_value = sc.nextInt();

        if (k_value == 0) {
            long product_result = 1;
            for (int i = 1; i < p_value; i++) {
                product_result = (product_result * p_value) % MODULUS;
            }
            System.out.println(product_result);
            sc.close();
            return;
        }

        for (int i = 0; i < p_value; i++) {
            if (visited_array[i] == 0) {
                depth_first_search(i, i);
            }
        }

        for (int i = 1; i <= p_value; i++) {
            if (num_array[i] != 0) {
                divisor_list.add(i);
            }
        }

        long answer = 1;
        for (int i = 0; i < divisor_list.size(); i++) {
            long temp_sum = 0;
            int divisor_i = divisor_list.get(i);
            for (int j = 0; j < divisor_list.size() && (long)divisor_list.get(j) * divisor_list.get(j) <= divisor_i; j++) {
                int divisor_j = divisor_list.get(j);
                if (divisor_i % divisor_j == 0) {
                    int a = divisor_i / divisor_j;
                    int b = divisor_j;
                    temp_sum += (long) a * num_array[a];
                    if (a != b) {
                        temp_sum += (long) b * num_array[b];
                    }
                    temp_sum %= MODULUS;
                }
            }
            int count_divisor = num_array[divisor_i];
            for (int j = 0; j < count_divisor; j++) {
                answer = (answer * temp_sum) % MODULUS;
            }
        }
        System.out.println(answer);
        sc.close();
    }
}
